/* Chismoso docs: the phone menu and client-side search. No dependencies.
 * The search index (search-index.js) is generated by build.mjs and loaded on
 * first use, so pages that are only read never download it. */
(function () {
  'use strict';

  // ---- Phone menu ----------------------------------------------------------------
  var menuBtn = document.querySelector('.menu-btn');
  var nav = document.getElementById('docs-nav');
  if (menuBtn && nav) {
    menuBtn.addEventListener('click', function () {
      var open = menuBtn.getAttribute('aria-expanded') !== 'true';
      menuBtn.setAttribute('aria-expanded', String(open));
      document.body.classList.toggle('nav-open', open);
      if (open) {
        var cur = nav.querySelector('[aria-current]');
        if (cur) cur.scrollIntoView({ block: 'nearest' });
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && document.body.classList.contains('nav-open')) {
        menuBtn.setAttribute('aria-expanded', 'false');
        document.body.classList.remove('nav-open');
        menuBtn.focus();
      }
    });
  }

  // ---- Search -----------------------------------------------------------------------
  var form = document.querySelector('[data-search]');
  if (!form) return;
  var input = form.querySelector('input');
  var box = form.querySelector('.search-results');
  var index = null, loading = null, results = [], active = -1;

  function loadIndex() {
    if (index) return Promise.resolve(index);
    if (loading) return loading;
    loading = new Promise(function (resolve) {
      var s = document.createElement('script');
      // Same folder as this script.
      var me = document.querySelector('script[src$="docs.js"]');
      s.src = me ? me.src.replace(/docs\.js(\?.*)?$/, 'search-index.js') : 'search-index.js';
      s.onload = function () { index = window.CHISMOSO_SEARCH || []; resolve(index); };
      s.onerror = function () { index = []; resolve(index); };
      document.head.appendChild(s);
    });
    return loading;
  }

  function norm(s) { return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }

  // Every word must appear somewhere; titles and headings count most.
  function search(q) {
    var words = norm(q).split(/\s+/).filter(Boolean);
    if (!words.length) return [];
    var out = [];
    index.forEach(function (e) {
      var p = norm(e.p), h = norm(e.h), x = norm(e.x), score = 0;
      for (var i = 0; i < words.length; i++) {
        var w = words[i], s = 0;
        if (h.indexOf(w) !== -1) s += h.indexOf(w) === 0 ? 12 : 8;
        if (p.indexOf(w) !== -1) s += 5;
        if (x.indexOf(w) !== -1) s += 1 + Math.min(3, x.split(w).length - 2);
        if (!s) return;
        score += s;
      }
      if (!e.h) score += 2; // the page itself, a little ahead of its sections
      out.push({ e: e, score: score });
    });
    out.sort(function (a, b) { return b.score - a.score; });
    return out.slice(0, 8).map(function (r) { return r.e; });
  }

  function snippet(text, q) {
    var words = norm(q).split(/\s+/).filter(Boolean);
    var t = norm(text), at = -1;
    for (var i = 0; i < words.length && at === -1; i++) at = t.indexOf(words[i]);
    var start = Math.max(0, at - 40);
    var s = text.slice(start, start + 140);
    return (start > 0 ? '…' : '') + s + (start + 140 < text.length ? '…' : '');
  }

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }

  function show(q) {
    results = search(q);
    active = results.length ? 0 : -1;
    box.textContent = '';
    if (!q.trim()) return hide();
    if (!results.length) {
      box.appendChild(el('p', 'sr-empty', 'Nothing found for “' + q + '”.'));
    }
    results.forEach(function (r, i) {
      var a = el('a', 'sr-item');
      a.href = r.u;
      a.id = 'sr-' + i;
      a.setAttribute('role', 'option');
      a.appendChild(el('span', 'sr-title', r.h || r.p));
      a.appendChild(el('span', 'sr-where', r.h ? r.p : r.s));
      if (r.x) a.appendChild(el('span', 'sr-text', snippet(r.x, q)));
      box.appendChild(a);
    });
    box.hidden = false;
    input.setAttribute('aria-expanded', 'true');
    mark();
  }
  function hide() {
    box.hidden = true;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
  }
  function mark() {
    Array.prototype.forEach.call(box.querySelectorAll('.sr-item'), function (a, i) {
      a.setAttribute('aria-selected', String(i === active));
    });
    if (active >= 0) {
      input.setAttribute('aria-activedescendant', 'sr-' + active);
      var cur = document.getElementById('sr-' + active);
      if (cur) cur.scrollIntoView({ block: 'nearest' });
    }
  }

  input.addEventListener('focus', loadIndex);
  input.addEventListener('input', function () {
    var q = input.value;
    loadIndex().then(function () { if (input.value === q) show(q); });
  });
  input.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown' && results.length) { e.preventDefault(); active = (active + 1) % results.length; mark(); }
    else if (e.key === 'ArrowUp' && results.length) { e.preventDefault(); active = (active - 1 + results.length) % results.length; mark(); }
    else if (e.key === 'Escape') { if (!box.hidden) { e.stopPropagation(); hide(); } else { input.value = ''; input.blur(); } }
  });
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (active >= 0 && results[active]) location.href = results[active].u;
  });
  document.addEventListener('click', function (e) { if (!form.contains(e.target)) hide(); });
  // "/" focuses search, unless you're typing somewhere.
  document.addEventListener('keydown', function (e) {
    if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey) return;
    var t = document.activeElement && document.activeElement.tagName;
    if (/INPUT|TEXTAREA|SELECT/.test(t)) return;
    e.preventDefault();
    input.focus();
  });
})();
